-- FINAGRO Web — financing contracts, component schedule, balances and hostile tenancy tests.
begin;
create schema test_financing;
create function test_financing.ok(v boolean,m text)returns void language plpgsql set search_path=''as $$begin if v is not true then raise exception 'TEST FAILED: %',m;end if;end$$;
create function test_financing.fails(q text,m text)returns void language plpgsql set search_path=''as $$declare a text;begin begin execute q;set constraints all immediate;exception when others then a=sqlerrm;set constraints all deferred;if position(m in a)=0 then raise exception 'TEST FAILED expected %, got %',m,a;end if;return;end;raise exception 'TEST FAILED expected %',m;end$$;
create function test_financing.affected(q text)returns integer language plpgsql set search_path=''as $$declare n integer;begin execute q;get diagnostics n=row_count;return n;end$$;
grant usage on schema test_financing to authenticated;grant execute on all functions in schema test_financing to authenticated;
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values
('f1000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','fin-a@test','x',now(),'{}','{}',now(),now()),
('f2000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','fin-b@test','x',now(),'{}','{}',now(),now()),
('f1000000-0000-0000-0000-000000000003','00000000-0000-0000-0000-000000000000','authenticated','authenticated','fin-read@test','x',now(),'{}','{}',now(),now());
insert into public.organizations(id,legal_name)values('f1000000-0000-0000-0000-000000000010','Fin A'),('f2000000-0000-0000-0000-000000000020','Fin B');select private.seed_default_roles('f1000000-0000-0000-0000-000000000010','f1000000-0000-0000-0000-000000000001');select private.seed_default_roles('f2000000-0000-0000-0000-000000000020','f2000000-0000-0000-0000-000000000002');insert into public.memberships(organization_id,user_id,role_id)select 'f1000000-0000-0000-0000-000000000010','f1000000-0000-0000-0000-000000000003',id from public.roles where organization_id='f1000000-0000-0000-0000-000000000010' and name='Somente leitura';
insert into public.farms(id,organization_id,name)values('f1000000-0000-0000-0000-000000000101','f1000000-0000-0000-0000-000000000010','A1'),('f1000000-0000-0000-0000-000000000102','f1000000-0000-0000-0000-000000000010','A2'),('f2000000-0000-0000-0000-000000000101','f2000000-0000-0000-0000-000000000020','B1');
insert into public.crop_seasons(id,organization_id,name,season_type)values('f1000000-0000-0000-0000-000000000201','f1000000-0000-0000-0000-000000000010','2026/27','PRINCIPAL'),('f2000000-0000-0000-0000-000000000201','f2000000-0000-0000-0000-000000000020','B','PRINCIPAL');
insert into public.chart_accounts(id,organization_id,code,name,managerial_type,nature,allows_allocation)values('f1000000-0000-0000-0000-000000000301','f1000000-0000-0000-0000-000000000010','1','Entrada','OUTRO','NEUTRA',true),('f1000000-0000-0000-0000-000000000302','f1000000-0000-0000-0000-000000000010','2','Principal','OUTRO','NEUTRA',true),('f1000000-0000-0000-0000-000000000303','f1000000-0000-0000-0000-000000000010','3','Juros','OUTRO','NEUTRA',true),('f1000000-0000-0000-0000-000000000304','f1000000-0000-0000-0000-000000000010','4','Encargos','OUTRO','NEUTRA',true),('f2000000-0000-0000-0000-000000000301','f2000000-0000-0000-0000-000000000020','B','B','OUTRO','NEUTRA',true);
insert into public.parties(id,organization_id,name,party_type)values('f1000000-0000-0000-0000-000000000401','f1000000-0000-0000-0000-000000000010','Banco A','FORNECEDOR'),('f2000000-0000-0000-0000-000000000401','f2000000-0000-0000-0000-000000000020','Banco B','FORNECEDOR');insert into public.bank_accounts(id,organization_id,bank_name,account_number)values('f1000000-0000-0000-0000-000000000501','f1000000-0000-0000-0000-000000000010','Banco A','1'),('f2000000-0000-0000-0000-000000000501','f2000000-0000-0000-0000-000000000020','Banco B','2');
insert into public.allocation_rules(id,organization_id,crop_season_id,name,is_active)values('f1000000-0000-0000-0000-000000000601','f1000000-0000-0000-0000-000000000010','f1000000-0000-0000-0000-000000000201','Metade',false);insert into public.allocation_rule_items(organization_id,allocation_rule_id,farm_id,percentage)values('f1000000-0000-0000-0000-000000000010','f1000000-0000-0000-0000-000000000601','f1000000-0000-0000-0000-000000000101',50),('f1000000-0000-0000-0000-000000000010','f1000000-0000-0000-0000-000000000601','f1000000-0000-0000-0000-000000000102',50);update public.allocation_rules set is_active=true;
insert into public.financing_contracts(id,organization_id,creditor_party_id,bank_account_id,contract_number,issued_on,contracted_amount,installment_count,crop_season_id,farm_id,principal_chart_account_id,created_by)values('f2000000-0000-0000-0000-000000000701','f2000000-0000-0000-0000-000000000020','f2000000-0000-0000-0000-000000000401','f2000000-0000-0000-0000-000000000501','CONTRATO-B','2026-01-01',1,1,'f2000000-0000-0000-0000-000000000201','f2000000-0000-0000-0000-000000000101','f2000000-0000-0000-0000-000000000301','f2000000-0000-0000-0000-000000000002');
set local role authenticated;select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','f1000000-0000-0000-0000-000000000001',true);
select test_financing.fails($$select public.create_financing_contract_with_schedule('f1000000-0000-0000-0000-000000000010','f1000000-0000-0000-0000-000000000401','ZERO',null,0,'2026-01-01',null,1,null,null,'f1000000-0000-0000-0000-000000000101',null,'SAC',null,null,null,null,false,null,null,null,null,'f1000000-0000-0000-0000-000000000302',null,null,false,'[{"number":1,"due_date":"2027-01-01","principal":0,"interest":0}]')$$,'PRINCIPAL_MUST_BE_POSITIVE');
select test_financing.fails($$select public.create_financing_contract_with_schedule('f1000000-0000-0000-0000-000000000010','f2000000-0000-0000-0000-000000000401','CROSS',null,1,'2026-01-01',null,1,null,null,'f1000000-0000-0000-0000-000000000101',null,'SAC',null,null,null,null,false,null,null,null,null,'f1000000-0000-0000-0000-000000000302',null,null,false,'[{"number":1,"due_date":"2027-01-01","principal":1,"interest":0}]')$$,'ACTIVE_CREDITOR');
select test_financing.fails($$select public.create_financing_contract_with_schedule('f1000000-0000-0000-0000-000000000010','f1000000-0000-0000-0000-000000000401','INCOMP',null,100,'2026-01-01',null,2,null,null,'f1000000-0000-0000-0000-000000000101',null,'SAC',null,null,null,null,false,null,null,null,null,'f1000000-0000-0000-0000-000000000302',null,null,false,'[{"number":1,"due_date":"2027-01-01","principal":50,"interest":0}]')$$,'SCHEDULE_INCOMPLETE');
select set_config('test.contract',(select public.create_financing_contract_with_schedule('f1000000-0000-0000-0000-000000000010','f1000000-0000-0000-0000-000000000401','FIN-2147','Crédito rural',2147000,'2026-09-01','2026-09-02',5,'f1000000-0000-0000-0000-000000000501','f1000000-0000-0000-0000-000000000201',null,'f1000000-0000-0000-0000-000000000601','CRONOGRAMA_INFORMADO',8.5,'AA','PREFIXADO',null,false,null,null,2147000,'f1000000-0000-0000-0000-000000000301','f1000000-0000-0000-0000-000000000302','f1000000-0000-0000-0000-000000000303','f1000000-0000-0000-0000-000000000304',false,'[{"number":1,"due_date":"2027-03-10","principal":429400,"interest":72500,"charges":[{"type":"TARIFA","amount":100.01}]},{"number":2,"due_date":"2027-09-10","principal":429400,"interest":65000,"charges":[]},{"number":3,"due_date":"2028-03-10","principal":429400,"interest":55000,"charges":[]},{"number":4,"due_date":"2028-09-10","principal":429400,"interest":45000,"charges":[]},{"number":5,"due_date":"2029-03-10","principal":429400,"interest":35000,"charges":[]}]')::text),true);
select test_financing.ok((select contracted_amount=2147000 and scheduled_principal=2147000 and received_amount=2147000 and principal_balance=2147000 from public.v_financing_contract_summary where id=current_setting('test.contract')::uuid),'contract, receipt and exact principal');
select test_financing.ok((select count(*)=1 from public.financial_entries where source_type='FINANCIAMENTO' and entry_direction='ENTRADA'),'one credit movement');select test_financing.ok((select count(*)=5 and sum(amount)=2147000 from public.financial_entries where id in(select principal_entry_id from public.financing_installments where financing_contract_id=current_setting('test.contract')::uuid)),'five principal outflows without third movement');select test_financing.ok((select count(*)=10 from public.entry_allocations where financial_entry_id in(select principal_entry_id from public.financing_installments where financing_contract_id=current_setting('test.contract')::uuid)),'allocation snapshot per principal entry');
update public.allocation_rule_items set percentage=60 where allocation_rule_id='f1000000-0000-0000-0000-000000000601' and farm_id='f1000000-0000-0000-0000-000000000101';update public.allocation_rule_items set percentage=40 where allocation_rule_id='f1000000-0000-0000-0000-000000000601' and farm_id='f1000000-0000-0000-0000-000000000102';select test_financing.ok((select count(*)=10 from public.entry_allocations where financial_entry_id in(select principal_entry_id from public.financing_installments where financing_contract_id=current_setting('test.contract')::uuid) and percentage=50),'rate allocation is historical snapshot');
select set_config('test.p1',(select principal_entry_id::text from public.financing_installments where financing_contract_id=current_setting('test.contract')::uuid and installment_number=1),true);select set_config('test.i1',(select interest_entry_id::text from public.financing_installments where financing_contract_id=current_setting('test.contract')::uuid and installment_number=1),true);select set_config('test.s1',(select public.create_settlement('f1000000-0000-0000-0000-000000000010',current_setting('test.p1')::uuid,'f1000000-0000-0000-0000-000000000501',null,now(),429400,null,null)::text),true);select test_financing.ok((select principal_paid=429400 and principal_balance=1717600 from public.v_financing_contract_summary where id=current_setting('test.contract')::uuid),'one principal payment reduces debt');select public.create_settlement('f1000000-0000-0000-0000-000000000010',current_setting('test.i1')::uuid,'f1000000-0000-0000-0000-000000000501',null,now(),72500,null,null);select test_financing.ok((select principal_balance=1717600 from public.v_financing_contract_summary where id=current_setting('test.contract')::uuid),'interest payment does not reduce debt');select test_financing.fails(format('select public.create_settlement(%L,%L,%L,null,now(),1,null,null)','f1000000-0000-0000-0000-000000000010',current_setting('test.p1'),'f1000000-0000-0000-0000-000000000501'),'CANNOT_EXCEED');select public.reverse_settlement(current_setting('test.s1')::uuid,'estorno de teste','PENDENTE');select test_financing.ok((select principal_balance=2147000 from public.v_financing_contract_summary where id=current_setting('test.contract')::uuid),'principal reversal restores debt');select test_financing.fails(format('update public.financing_contracts set contracted_amount=1 where id=%L',current_setting('test.contract')),'WITH_MOVEMENTS_IS_IMMUTABLE');
select test_financing.ok((select count(*)=0 from public.financing_contracts where organization_id='f2000000-0000-0000-0000-000000000020'),'organization A cannot view B contract');select test_financing.ok(test_financing.affected($$update public.financing_contracts set notes='hostile' where id='f2000000-0000-0000-0000-000000000701'$$)=0,'organization A cannot alter B contract');
reset role;set local role authenticated;select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','f1000000-0000-0000-0000-000000000003',true);select test_financing.ok((select count(*)=1 from public.financing_contracts),'read only can view');select test_financing.fails($$select public.create_financing_contract_with_schedule('f1000000-0000-0000-0000-000000000010','f1000000-0000-0000-0000-000000000401','READ',null,1,'2026-01-01',null,1,null,null,'f1000000-0000-0000-0000-000000000101',null,'SAC',null,null,null,null,false,null,null,null,null,'f1000000-0000-0000-0000-000000000302',null,null,false,'[{"number":1,"due_date":"2027-01-01","principal":1,"interest":0}]')$$,'PERMISSION_DENIED');
rollback;
